SELECT id, account_id, amount, txn_time, LAG(amount, 1) OVER (PARTITION BY merchant ORDER BY amount, id) prev_amount, AVG(amount) OVER (ORDER BY txn_time, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) amount_avg_5, LAST_VALUE(merchant) IGNORE NULLS OVER (PARTITION BY account_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_merchant FROM transactions;
